// QueryMembers queries the members edge of a Fleet.
func (c *FleetClient) QueryMembers(_m *Fleet) *FleetMemberQuery {
	query := (&FleetMemberClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(fleet.Table, fleet.FieldID, id),
			sqlgraph.To(fleetmember.Table, fleetmember.FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, fleet.MembersTable, fleet.MembersColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

